"""
author:wjw
分析:跟decode_1720类似，从range(n)中挑数作为first，然后判断decode后的数是否为range(n)的一个排列
优化:first=x^encoded[1]^encoded[3]^....,其中x为range(1,n+1)的异或和。
"""
import time


def firstdecode(encode, first):
    n = len(encode) + 1
    de = [first]
    ans = first
    for i in range(len(encode)):
        ans = ans ^ encode[i]
        de.append(ans)

    return de


class Solution:
    def decode(self, encoded):

        n = len(encoded) + 1
        ans = 0
        for i in range(1, n + 1):
            ans = ans ^ i

        gap_sum = 0
        for i in range(1, n - 1, 2):
            gap_sum = gap_sum ^ encoded[i]
        first = ans ^ gap_sum

        res = firstdecode(encoded, first)
        print(len(set(res)))
        print(max(res))
        print(min(res))
        return res


